const webhookData = $('📩 Webhook MELI').item.json;
const token = $input.item.json.access_token;
const resourcePath = webhookData.body.resource;
const leadId = resourcePath.replace('/vis/leads/', '');

return {
  json: {
    lead_id: leadId,
    user_id: webhookData.body.user_id,
    received_at: webhookData.body.received,
    access_token: token
  }
};

const leadDetails = $input.item.json; // ahora viene de 🚗 Fetch Item1
const prev = $('Mapear Lead').item.json;

let item_titulo = null;
let item_precio = null;
let item_permalink = null;
let item_condition = null;
let item_thumbnail = null;
let item_status = null;
let item_currency = null;
let item_descripcion = null;
let seller_address = null;
let seller_zip = null;
let seller_lat = null;
let seller_lng = null;
let asesor_phone = null;
let asesor_phone2 = null;

try {
  const item = $('🚗 Fetch Item').item.json;
  if (item && item.id) {
    item_titulo = item.title || null;
    item_precio = item.price || null;
    item_permalink = item.permalink || null;
    item_condition = item.condition || null;
    item_thumbnail = item.thumbnail || null;
    item_status = item.status || null;
    item_currency = item.currency_id || null;
    seller_address = item.seller_address?.address_line || null;
    seller_zip = item.seller_address?.zip_code || null;
    seller_lat = item.seller_address?.latitude?.toString() || null;
    seller_lng = item.seller_address?.longitude?.toString() || null;
    asesor_phone = item.seller_contact?.phone?.toString() || null;
    asesor_phone2 = item.seller_contact?.phone2?.toString() || null;
  }
} catch (e) {
  // 🚗 Fetch Item no ejecutó o no tiene output para este item
}

try {
  item_descripcion = $('📝 Fetch Descripción').item.json.plain_text || null;
} catch (e) {
  // 📝 Fetch Descripción no ejecutó o la publicación no tiene descripción
}

let lead_id = prev.lead_id;
if (lead_id) {
  lead_id = lead_id.replace('/leads', '').replace('/details', '').replace(/^\/+|\/+$/g, '');
}

// --- dealership desde el input directo (🚗 Fetch Item1) ---
let dealership = null;
const rawDealership = leadDetails?.details?.dealership || null;
if (rawDealership) {
  dealership = rawDealership.split('-')[0].trim();
}

return {
  json: {
    ...prev,
    lead_id,
    item_titulo,
    item_precio,
    item_permalink,
    item_condition,
    item_thumbnail,
    item_status,
    item_currency,
    item_descripcion,
    seller_address,
    seller_zip,
    seller_lat,
    seller_lng,
    asesor_phone,
    asesor_phone2,
    dealership,
    received_at: prev.received_at ? new Date(prev.received_at).toISOString().replace('T', ' ').substring(0, 19) : null
  }
};

const lead = $input.item.json;
const prev = $('⚙️ Preparar datos').item.json;

const escape = (str) => str ? str.toString().replace(/'/g, "''") : null;

return {
  json: {
    lead_id: prev.lead_id,
    user_id: prev.user_id,
    received_at: prev.received_at,
    access_token: prev.access_token,
    item_id: lead.item_id,
    buyer_id: lead.buyer_id,
    buyer_nombre: escape(lead.name),
    buyer_email: escape(lead.email),
    buyer_phone: escape(lead.phone),
    buyer_cuit: escape(lead.identification_number),
    contact_type: lead.contact_type,
    status: (!lead.buyer_id || lead.buyer_id === 0 || !lead.name) ? 'incomplete' : 'active'
  }
};

